      "id": "modern-c04-l16-p03-028",
      "title": "ラホールで完全独立を宣言する国民会議派",
      "body": [
        "1929年、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国民会議派</strong></span>は<strong class=\"source-bold\">パンジャーブ地方</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ラホール</strong></span>で大会を開き、若い<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ネルー</strong></span>を指導者として、今後の目標が「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">プールナ＝スワラージ</strong></span>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">完全独立</strong></span>）」であることを宣言した。"
      ],
      "plainBody": [
        "1929年、国民会議派はパンジャーブ地方のラホールで大会を開き、若いネルーを指導者として、今後の目標が「プールナ＝スワラージ（完全独立）」であることを宣言した。"
      ],
