      "body": [
        "「独立するなら、ヒンドゥー教徒とは別の国で！」、そう思った<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">全インド＝ムスリム連盟</strong></span>は、1940年、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ジンナー</strong></span>を指導者とするムスリム連盟の<strong class=\"source-bold\">ラホール大会</strong>で、ムスリムの清浄な国「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">パキスタン</strong></span>」の建設、つまりは<strong class=\"source-bold\">分離独立を決議</strong>したんだ。"
      ],
