      "body": [
        "そして、<strong class=\"source-bold\">この対立はインド独立まで続く</strong>ことになるよ。第二次世界大戦が始まっても、<strong class=\"source-bold\">国民会議派</strong>はガンディーを中心に<strong class=\"source-bold\">不服従運動を続け</strong>、さらには「<strong class=\"source-bold\">クイット＝インディア</strong>（インドから出ていけ！ つまり<strong class=\"source-bold\">即時独立</strong>ってこと）」を要求するなど、どんどん過激な運動をやったから、<strong class=\"source-bold\">非合法とされて弾圧された</strong>んだ。"
      ],
