      "title": "分離独立を求めて戦争に協力するムスリム連盟",
      "body": [
        "一方、<strong class=\"source-bold\">ムスリム連盟</strong>は、インド独立の際に「ヒンドゥー国家とイスラーム国家」を分離独立させてくれるようイギリスに働きかけ、そのために<strong class=\"source-bold\">第二次世界大戦ではイギリスに協力</strong>したんだよ。"
      ],
      "plainBody": [
        "一方、ムスリム連盟は、インド独立の際に「ヒンドゥー国家とイスラーム国家」を分離独立させてくれるようイギリスに働きかけ、そのために第二次世界大戦ではイギリスに協力したんだよ。"
      ],
