      "body": [
        "第一次世界大戦前に結成された<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">サレカット＝イスラム</strong></span> <strong class=\"source-bold\">【</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">イスラーム同盟</strong></span><strong class=\"source-bold\">】</strong>が、オランダに弾圧されて力を失っていくなかで、<strong class=\"source-bold\">同盟内の左派グループ</strong>は労働組合と結びついて、<strong class=\"source-bold\">アジア最初の共産党</strong>となる<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">インドネシア共産党</strong></span>をつくったよ。"
      ],
