export const sourcePages = {
  "293": "<h2>293</h2>\n<h1><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第16回</strong></span> <span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">戦間期の西アジア・南アジア・東南アジア</strong></span></h1>\n<p>それじゃあ、第一次世界大戦後のアジアは2回に分けて見ていくよ。今回は西アジア・東南アジア・南アジア。各地で民族運動が盛り上がるよ！</p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">大きくつかもう！</span></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">1</strong></span></td><td><strong class=\"source-bold\">トルコ革命</strong></td><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">294〜297ページ</span></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">2</strong></span></td><td><strong class=\"source-bold\">戦間期の西アジア・アラブ諸国</strong></td><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">297〜301ページ</span></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">3</strong></span></td><td><strong class=\"source-bold\">インドの民族運動</strong></td><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">301〜305ページ</span></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">4</strong></span></td><td><strong class=\"source-bold\">東南アジアの民族運動</strong></td><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">305〜309ページ</span></td></tr></tbody></table></div>\n<blockquote><p>ヨーロッパでは実現した民族自決が、アジア・アフリカでは実現しない……。民族運動の高揚が、今回のポイントだよ</p></blockquote>\n<p>アメリカ大統領<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">ウィルソンの十四カ条</strong></u>で主張された「<span data-source-color=\"red\" style=\"color:#e52715\">民族<ruby>自決<rt>じけつ</rt></ruby></span>」がパリ<ruby>講和<rt>こうわ</rt></ruby>会議の原則となり、ヨーロッパでは新興の独立国が誕生したよね。こうなると、植民地になっているアジア・アフリカ、特に<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">インド</strong></u>や<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">東南アジア</strong></u>では「次はオレたちの民族自決だぁ〜」って、<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">民族運動が盛り上がった</strong></u>。でも、<ruby>列強<rt>れっきょう</rt></ruby>は植民地を独立させる気はほとんどない……。こりゃ、問題が大きくなりそうな予感がするね。</p>\n<p>さらに、ずっとイスラーム世界の中心として君臨してきた<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">オスマン帝国</strong></u>も、第一次世界大戦に敗れて、ついに最期を迎えるよ。西アジアでの<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">トルコ革命</strong></u>、<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">イラン＝クーデタ</strong></u>、さらに<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">アラブ諸国</strong></u>の動きまで、一気に確認しよう！</p>\n<p>それじゃあ、戦間期のアジア、いってみよ〜。</p>",
  "294": "<h2>294</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第16回</strong></span> 戦間期の西アジア・南アジア・東南アジア</p>\n<h2><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">1</strong></span> <span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">トルコ革命</strong></span></h2>\n<h3><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">敗戦のドサクサに紛れて、ギリシア軍が攻め込んできた！</strong></span></h3>\n<p><strong class=\"source-bold\">第一次世界大戦で同盟国（ドイツ側）</strong>の一員だった<strong class=\"source-bold\">オスマン帝国</strong>（トルコ）は<strong class=\"source-bold\">敗戦国</strong>となり、戦争が終わるとさらなる試練が待っていた。まず、戦争中に<strong class=\"source-bold\">シリアやイラク</strong>などの<strong class=\"source-bold\">アラブ地域をイギリス軍に<ruby>占領<rt>せんりょう</rt></ruby></strong>され、大戦末期には連合軍にアナトリア（小アジア）も占領されたんだ。さらに<strong class=\"source-bold\">クルド人</strong>や<strong class=\"source-bold\">アルメニア人</strong>の独立運動も起きて、トルコ人の国がバラバラにされるような危機的状況になっちゃったよ。</p>\n<p>これに対し、かつての「統一と進歩委員会（青年トルコ）」の連中は「いくらなんでもひどい！ トルコ人の権利を守れ！」って、国内外に訴えた。ところが、<strong class=\"source-bold\">イスタンブル政府（オスマン帝国のスルタン政府</strong>のことね）は、スルタンの地位を守るために「イギリスを怒らせないように……」ってことしか考えてなかった。</p>\n<p>これを見て「エーゲ海をまたぐ“大ギリシア国家”をつくりたい」って思った<strong class=\"source-bold\">ギリシア</strong>は、イギリスに「<strong class=\"source-bold\">オスマン帝国からアナトリアを取りたい</strong>」と相談したら、「なら、取っちゃえば」って言われた。こうして、降伏したはずの<strong class=\"source-bold\">オスマン帝国</strong>に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ギリシア軍が<ruby>侵入<rt>しんにゅう</rt></ruby></strong></span>し（<strong class=\"source-bold\">ギリシア＝トルコ戦争</strong>）、エーゲ海沿岸の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">イズミル</strong></span> <strong class=\"source-bold\">【</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スミルナ</strong></span><strong class=\"source-bold\">】</strong>を占領すると、さらに<strong class=\"source-bold\">アナトリアの内陸部に攻め込んできた</strong>。</p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">クローズアップ</span> <span data-source-color=\"black\" data-source-background=\"pink\" style=\"color:#222222;background-color:#f0a0a0\"><strong class=\"source-bold\">トルコ革命</strong></span></h3>\n<blockquote><p><span data-source-color=\"red\" style=\"color:#e52715\">●</span> 第一次世界大戦における敗戦……<strong class=\"source-bold\">オスマン帝国は同盟国側</strong>で参戦</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span> <strong class=\"source-bold\">ギリシア＝トルコ戦争</strong> ［1919〜22］ <span data-source-color=\"green\" style=\"color:#315837\">➡</span>ギリシア軍が<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">イズミル</strong></span>を占領</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span> トルコ軍人：<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ムスタファ＝ケマル</strong></span><strong class=\"source-bold\">【</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ケマル＝パシャ</strong></span><strong class=\"source-bold\">】</strong>による祖国解放運動</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">▶</span> <strong class=\"source-bold\">トルコ大国民議会</strong>を開催 ［1920］ <span data-source-color=\"green\" style=\"color:#315837\">➡</span><strong class=\"source-bold\">アンカラ政府</strong>を形成</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">セーヴル条約</strong></span> ［1920.8］ ……<strong class=\"source-bold\">イスタンブル政府と連合国</strong>の<ruby>講和<rt>こうわ</rt></ruby>条約</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">トルコ革命</strong></span> ［1919〜23］ ……<strong class=\"source-bold\">ムスタファ＝ケマル</strong>が指導</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スルタン制廃止</strong></span> ［1922］ ＝<strong class=\"source-bold\">オスマン帝国の滅亡</strong></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ローザンヌ条約</strong></span> ［1923］ ……<strong class=\"source-bold\">トルコ新政府が連合国と結んだ</strong>新しい講和条約</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">トルコ共和国</strong></span>成立 ［1923.10］ ……首都：<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アンカラ</strong></span></p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span> トルコ共和国の近代化政策……脱イスラームとトルコ民族主義を強調</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">カリフ制廃止</strong></span> ［1924］ ……完全な<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>政教分離<rt>せいきょうぶんり</rt></ruby></strong></span>の実現</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span> <strong class=\"source-bold\">トルコ共和国憲法</strong> ［1924］ ……<strong class=\"source-bold\">脱イスラーム化</strong>、国家制度の世俗化</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">文字改革</strong></span> ［1928］ ……<strong class=\"source-bold\">アラビア文字を廃止</strong>して<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ローマ字を採用</strong></span></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">女性解放</strong></span>……<strong class=\"source-bold\">チャドル【ヴェール】</strong>の廃止、<strong class=\"source-bold\">一夫一婦制</strong>の採用、<strong class=\"source-bold\">女性参政権</strong> ［1934］</p></blockquote>",
  "295": "<h2>295</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">1</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">トルコ革命</u></p>\n<h3><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">ムスタファ＝ケマルが立ち上がったけど……<ruby>亡国<rt>ぼうこく</rt></ruby>のセーヴル条約が結ばれた！</strong></span></h3>\n<p>「このままじゃ国がなくなる」と思ったトルコ人たちは抵抗したけど、運動が一つにまとまらなかった。そこに<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ムスタファ＝ケマル</strong></span>が登場！ ケマルは<strong class=\"source-bold\">各地の軍人や旧青年トルコのメンバー</strong>に呼びかけて、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アンカラ</strong></span>で<strong class=\"source-bold\">トルコ大国民議会</strong>を開いて、<strong class=\"source-bold\">革命政権（アンカラ政府）</strong>をつくった。ここから<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">トルコ革命</strong></span>が始まるんだ。</p>\n<p>ただ、<strong class=\"source-bold\">革命政府の敵はギリシア軍だけじゃなかった</strong>。英仏などの連合軍がイスタンブルを占領すると、<strong class=\"source-bold\">イスタンブル（オスマン帝国）政府</strong>はアンカラの革命政府を倒すために<strong class=\"source-bold\">連合国に接近</strong>！、1920年には<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">セーヴル条約</strong></span>を結んで連合国の要求をほぼ受け入れた。というか、この条約は<strong class=\"source-bold\">独立を失うような内容</strong>だよ。<strong class=\"source-bold\">オスマン帝国領は連合国に分割</strong>されて約3分の1になり、<strong class=\"source-bold\">アラブ地域</strong>は英仏の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>委任統治領<rt>いにんとうちりょう</rt></ruby></strong></span>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">メソポタミア</strong></span>・<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヨルダン</strong></span>・<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">パレスチナ</strong></span>は<strong class=\"source-bold\">イギリス</strong>、<strong class=\"source-bold\">シリア・レバノン</strong>は<strong class=\"source-bold\">フランス</strong>）、アナトリア南西部はイタリアの支配地域、<strong class=\"source-bold\">キプロス島</strong>は<strong class=\"source-bold\">イギリス</strong>に<ruby>割譲<rt>かつじょう</rt></ruby>、さらに<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">イズミル</strong></span>は<strong class=\"source-bold\">ギリシア</strong>が行政権を持つことになった。そして<strong class=\"source-bold\"><ruby>治外法権<rt>ちがいほうけん</rt></ruby>（カピチュレーション）</strong>が復活して、<strong class=\"source-bold\">軍備</strong>も制限されたんだ。こんなの独立国じゃないよ。</p>\n<h3><strong class=\"source-bold\">〈セーヴル条約 ［1920］ によるオスマン帝国領の分割〉</strong></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td></tr><tr><td><span data-source-marker=\"point\" data-source-color=\"red\" style=\"color:#e52715\">●</span><em data-source-italic=\"true\" style=\"font-style:italic\">イスタンブル</em></td><td><span data-source-marker=\"point\" data-source-color=\"red\" style=\"color:#e52715\">●</span><em data-source-italic=\"true\" style=\"font-style:italic\">アンカラ</em></td><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><em data-source-italic=\"true\" style=\"font-style:italic\">アルメニア国家</em></span></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><em data-source-italic=\"true\" style=\"font-style:italic\">ギリシア領</em></span></td><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">トルコ人国家</span></td><td></td></tr><tr><td><em data-source-italic=\"true\" style=\"font-style:italic\">イズミル</em></td><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><em data-source-italic=\"true\" style=\"font-style:italic\">イタリア支配地域</em></span></td><td></td></tr><tr><td>キプロス島</td><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><em data-source-italic=\"true\" style=\"font-style:italic\">フランス支配地域</em></span></td><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><em data-source-italic=\"true\" style=\"font-style:italic\">イギリス支配地域</em></span></td></tr><tr><td><em data-source-italic=\"true\" style=\"font-style:italic\"><strong class=\"source-bold\">レバノン</strong></em></td><td><em data-source-italic=\"true\" style=\"font-style:italic\"><strong class=\"source-bold\">シリア</strong></em></td><td></td></tr><tr><td><em data-source-italic=\"true\" style=\"font-style:italic\"><strong class=\"source-bold\">ヨルダン</strong></em></td><td><em data-source-italic=\"true\" style=\"font-style:italic\"><strong class=\"source-bold\">イラク</strong></em></td><td></td></tr></tbody></table></div>\n<blockquote><p>これだけ領土がなくなったら、もはや独立国とはいえないよ</p></blockquote>\n<p><span data-source-border=\"green\" style=\"border:1px solid #859476;padding:0 0.2em\"><span data-source-marker=\"dashed-line\" data-source-color=\"red\" style=\"color:#e52715\">┄</span> ローザンヌ条約［1923］によるトルコ共和国の国境</span></p>\n<h3><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">ローザンヌ条約で独立を維持し、ケマルがトルコ共和国を樹立した！</strong></span></h3>\n<p>ここでよく考えてね。<strong class=\"source-bold\">ギリシア軍が攻めてきたのは戦後</strong>だから、第一次世界大戦の講和条約である<strong class=\"source-bold\">セーヴル条約にギリシアへの領土割譲が入っている</strong>のは、どう考えてもおかしい！ <strong class=\"source-bold\">ケマル</strong>は「だったらこっちも実力で取り返すしかない！」と思い、議会から全権を得て<strong class=\"source-bold\">ギリシア軍との戦いに突入</strong>したんだ。この間に、連合国にプレッシャーをかけるためにロシアのソヴィエト政権に接近！ 初めて国際的に承認されたよ。さらに激戦の末にギリシア軍をサカリヤ川の戦いで破ると、1922年、</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦間期と第二次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "296": "<h2>296</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第16回</strong></span> 戦間期の西アジア・南アジア・東南アジア</p>\n<p>ついに<strong class=\"source-bold\">ギリシア軍を撃退</strong>して<strong class=\"source-bold\">イズミルを奪い返した</strong>。そして戦争を指揮するなかで、<strong class=\"source-bold\">ムスタファ＝ケマル</strong>はスルタンに妥協しそうな連中を抑え込み、<strong class=\"source-bold\">権力を確立</strong>したよ。さすがに連合国もケマルの力を認めるしかなくなり、<strong class=\"source-bold\">条約を結び直す</strong>ことになった。</p>\n<p>交渉開始が決まると、ケマルは「<strong class=\"source-bold\">スルタンが、また連合国に妥協したらマズい</strong>……」と思ったんだ。1度は条約を結び直せても、2度目はない！ ケマルは<strong class=\"source-bold\">大国民議会</strong>を主導して<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スルタン制の廃止</strong></span>を決議し、1922年、最後のスルタン（メフメト6世）がマルタに<ruby>亡命<rt>ぼうめい</rt></ruby>して、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">オスマン帝国が滅亡</strong></span>した。ただ、スルタンの<ruby>従兄弟<rt>いとこ</rt></ruby>がカリフになったから、<strong class=\"source-bold\">まだオスマン家はカリフ</strong>だよ。</p>\n<p>そして1923年には、<strong class=\"source-bold\">アンカラ政府</strong>が連合国との新しい<ruby>講和<rt>こうわ</rt></ruby>条約<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ローザンヌ条約</strong></span>を結んだよ。トルコは<strong class=\"source-bold\">イスタンブル周辺やイズミル、東トラキア</strong>などを回復し、<strong class=\"source-bold\">治外法権や軍備制限の撤廃</strong>にも成功したんだ。</p>\n<p>こうして独立を維持したケマルは議会で<strong class=\"source-bold\">共和国宣言を可決</strong>し、正式に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">トルコ共和国</strong></span>が樹立されたよ。首都は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アンカラ</strong></span>、<strong class=\"source-bold\">初代大統領</strong>はもちろん<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ムスタファ＝ケマル</strong></span>だ。</p>\n<h3><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">トルコ共和国の近代化政策。キーワードは「脱イスラーム」だ！</strong></span></h3>\n<p>トルコ共和国が成立すると、<strong class=\"source-bold\">立法機関となったトルコ大国民議会</strong>では、ケマルが結成した<strong class=\"source-bold\">トルコ人民党</strong>（のちの共和人民党）が主導権を握って、さまざまな近代化政策が進められたよ。キーワードは「<strong class=\"source-bold\">脱イスラーム</strong>」と「<strong class=\"source-bold\">トルコ民族主義</strong>」だ。これまでは<strong class=\"source-bold\">オスマン朝のスルタン＝カリフ制</strong>のもとでイスラーム教に基づく政治がおこなわれていたけど、ケマルは近代的な<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>政教分離<rt>せいきょうぶんり</rt></ruby></strong></span>を目指した。下の図を見ながら、オスマン帝国の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スルタン＝カリフ制</strong></span>が崩壊する過程を確認しよう。</p>\n<h3><strong class=\"source-bold\">〈スルタン＝カリフ制の崩壊〉</strong></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td><strong class=\"source-bold\">スルタン制廃止［1922］</strong></td><td></td><td><strong class=\"source-bold\">カリフ制廃止［1924］</strong></td></tr><tr><td><span data-source-border=\"red\" data-source-border-style=\"dashed\" data-source-cancellation=\"cross\" data-source-cancellation-color=\"red\" style=\"border:1px dashed #e52715;padding:0 0.2em;text-decoration:line-through;text-decoration-color:#e52715\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スルタン</strong></span></span> <strong class=\"source-bold\">＝ カリフ制</strong></td><td><span data-source-marker=\"outline-arrow\" data-source-color=\"black\" style=\"color:#222222\">⇨</span></td><td><span data-source-border=\"red\" data-source-border-style=\"dashed\" data-source-cancellation=\"cross\" data-source-cancellation-color=\"red\" style=\"border:1px dashed #e52715;padding:0 0.2em;text-decoration:line-through;text-decoration-color:#e52715\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スルタン</strong></span></span> <strong class=\"source-bold\">＝</strong> <span data-source-border=\"brown\" data-source-border-style=\"dashed\" data-source-cancellation=\"cross\" data-source-cancellation-color=\"brown\" style=\"border:1px dashed #a43725;padding:0 0.2em;text-decoration:line-through;text-decoration-color:#a43725\"><strong class=\"source-bold\">カリフ制</strong></span></td></tr><tr><td><strong class=\"source-bold\">1922年 廃止</strong><br><span data-source-marker=\"outline-arrow\" data-source-color=\"black\" style=\"color:#222222\">⇩</span><br><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">政治的権力を失う<br>（オスマン帝国滅亡）</strong></span><br><strong class=\"source-bold\">カリフ位は保持<br>（宗教的権威は<br>そのまま）</strong></td><td></td><td><strong class=\"source-bold\">1924年 廃止</strong><br><span data-source-marker=\"outline-arrow\" data-source-color=\"black\" style=\"color:#222222\">⇩</span><br><span data-source-color=\"brown\" style=\"color:#a43725\"><strong class=\"source-bold\">宗教的権威も失う<br>（政教分離）</strong></span></td></tr></tbody></table></div>\n<p>まず、反対派を抑えて<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">カリフ制を廃止</strong></span>するとともに、<strong class=\"source-bold\">イスラーム法廷</strong>やウラマー（イスラーム法学者）の養成機関だった<strong class=\"source-bold\">マドラサ</strong>を廃止したよ。これには、トルコ国内だけじゃなくて、<strong class=\"source-bold\">インドやイランなど世界のムスリムが反対した</strong>んだけど、「カリフ制を残すのは単なるオスマン帝国主義だ！」と、まったく取り合わなかった。さらに、<strong class=\"source-bold\">トルコ共和国憲法</strong>を制定して、<strong class=\"source-bold\"><ruby>主権在民<rt>しゅけんざいみん</rt></ruby></strong>や<strong class=\"source-bold\">一院制議会</strong>、<strong class=\"source-bold\">大統領制</strong>（任期4年）など近代的な国家制度に変え、1928年には憲法にあった「<strong class=\"source-bold\">イスラームが国教</strong>」という<strong class=\"source-bold\">条項も削除</strong>して、政治に対するイスラーム教の影響を排除した。こうし</p>",
  "297": "<h2>297</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">2</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">戦間期の西アジア・アラブ諸国</u></p>\n<p>てトルコは<strong class=\"source-bold\">政教分離を達成</strong>したんだね。</p>\n<p>その後、<strong class=\"source-bold\">イスラーム<ruby>暦<rt>れき</rt></ruby>を廃止</strong>して<ruby>西暦<rt>せいれき</rt></ruby>（太陽暦）を採用したり、<strong class=\"source-bold\">チャドル</strong>（ヴェール）の廃止や<strong class=\"source-bold\"><ruby>一夫一婦制<rt>いっぷいっぷせい</rt></ruby></strong>の採用など、<ruby>男尊女卑<rt>だんそんじょひ</rt></ruby>のイスラームの慣習をなくして<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">女性解放</strong></span>を実現すると、1934年には<strong class=\"source-bold\">女性参政権</strong>を認めたよ。イスラーム世界じゃ、いまだに女性参政権がない国も多いからね。さらに、アラビア文字を廃止して<strong class=\"source-bold\">ローマ字（ラテン文字）を採用</strong>する<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">文字改革</strong></span>をおこなって国民の<ruby>識字率<rt>しきじりつ</rt></ruby>を高めた。また、<strong class=\"source-bold\">トルコ民族主義</strong>を高めるために、<strong class=\"source-bold\">トルコ語やトルコ史の教育や研究</strong>を進めさせたよ。</p>\n<p>こんなふうに一気にトルコを近代化したケマルに対し、大国民議会は「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アタテュルク</strong></span>（トルコの父）」って尊称を贈った。その一方で、ケマルは<strong class=\"source-bold\">憲法を無視して終身大統領</strong>になったり、<strong class=\"source-bold\">トルコ人民党の一党支配</strong>をつくったりと、かなり<ruby>独裁<rt>どくさい</rt></ruby>的な一面もあったよ。ただ、イスラームの伝統を消し去る徹底的な「脱イスラーム」を実現するには、このくらい権力がないと難しかったかもね。</p>\n<h2><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">2</strong></span> <span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">戦間期の西アジア・アラブ諸国</strong></span></h2>\n<h3><span data-source-color=\"brown\" style=\"color:#a43725\"><strong class=\"source-bold\">〈イラン〉</strong></span></h3>\n<h3><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">第一次世界大戦では、中立を宣言したのに英・露に<ruby>占領<rt>せんりょう</rt></ruby>された！</strong></span></h3>\n<p>1907年の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>英露<rt>えいろ</rt></ruby>協商</strong></span>で、<strong class=\"source-bold\">ロシアとイギリス</strong>の勢力圏に分割されたイランは、第一次世界大戦では中立を宣言したよ。ただ、英露に反発したイラン政府（ガージャール朝）はドイツと秘密交渉していた！。この動きに気づいた<strong class=\"source-bold\">イギリスとロシアがイランに軍を派遣</strong>するとトルコも出兵したから、戦場になっちゃった。そして、<strong class=\"source-bold\">ロシア革命<ruby>勃発<rt>ぼっぱつ</rt></ruby></strong>で<strong class=\"source-bold\">ロシア軍が撤退</strong>すると、イギリスがイランを独占しようと<ruby>侵攻<rt>しんこう</rt></ruby>してきて、<strong class=\"source-bold\">イランはイギリスに半植民地化</strong>されるような条約を結ばされたんだよ。</p>\n<h3><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">レザー＝ハーンのクーデタでパフレヴィー朝が成立！</strong></span></h3>\n<p>第一次世界大戦末期から、<strong class=\"source-bold\">イラン</strong>では<strong class=\"source-bold\">ロシアのソヴィエト政権（ソ連）と連携</strong>してイギリスに対抗しようという動きが起きたよ。もともとイラン人はトルコ系の<strong class=\"source-bold\">ガージャール朝に不満</strong>タラタラだったし、<strong class=\"source-bold\">イギリスの<ruby>侵略<rt>しんりゃく</rt></ruby>にも反発</strong>していたから、反英意識の強い北部では社会主義共和国を建設する動きまで起き始めた。こんなふうに、第一次世界大戦後のイランは大混乱だったんだ。</p>\n<p>この混乱を終わらせたのが、イラン軍人の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">レザー＝ハーン</strong></span>だよ。彼は<strong class=\"source-bold\">イギリスの支援</strong>でクーデタを起こし、近代的な軍を創設して各地の反対勢力を倒した。反面で、ソ連とも友好協定を結んでイギリスを<ruby>牽制<rt>けんせい</rt></ruby>し、<strong class=\"source-bold\">英ソ両国のバランスを取りながら権力を握った</strong>よ。そして、1924年に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ガージャール朝</strong></span>の<strong class=\"source-bold\">廃止</strong>を決定した国民議会の意向を受けて、翌年シャー（国王）に即位し、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">パフレヴィー朝</strong></span>が成立したんだ。</p>\n<p>その後もイランでは、<strong class=\"source-bold\">イギリスとソ連の思惑がぶつかった</strong>。でも<strong class=\"source-bold\">レザー＝シャー</strong>（国王になったから“シャー”だ！）は、イギリスとソ連の勢力均衡によって権力を維持すると、トルコにならって「脱イスラーム」と「西欧化」を進め、徴兵制</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦間期と第二次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "298": "<h2>298</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第16回</strong></span> 戦間期の西アジア・南アジア・東南アジア</p>\n<p>の導入や太陽暦の採用のほか、イラン民族主義を強調して、国号を他称の<strong class=\"source-bold\">ペルシア</strong>から<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">イラン</strong></span>に改称したよ。</p>\n<h3><span data-source-color=\"brown\" style=\"color:#a43725\"><strong class=\"source-bold\">〈英仏の委任<ruby>統治<rt>とうち</rt></ruby>となったアラブ諸国〉</strong></span></h3>\n<h3><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">アラブ諸国は、大戦中のイギリスの秘密外交に<ruby>翻弄<rt>ほんろう</rt></ruby>された！</strong></span></h3>\n<p>第一次世界大戦中の1915年、イギリスの駐エジプト高等弁務官<strong class=\"source-bold\">マクマホン</strong>は、アラブの指導者<strong class=\"source-bold\">フセイン（ハーシム家）</strong>との間で<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">フセイン・マクマホン協定</strong></span>を結んで、<strong class=\"source-bold\">アラブ人の対トルコ参戦</strong>と引き換えに、<strong class=\"source-bold\">戦後のアラブ人の独立</strong>を認めたよね。アラブ人たちは「戦争が終わったら、いよいよ自分たちの国ができる♪」と思ってトルコと戦ったんだよ。この時、アラブ人とともに戦ったイギリス人の情報将校（要はスパイだけど）がアラビアの<strong class=\"source-bold\">ローレンス</strong>だ。</p>\n<p>ところが、イギリスは翌年<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">サイクス・ピコ協定</strong></span>で、<strong class=\"source-bold\">英・仏・露</strong>の3国による<strong class=\"source-bold\">オスマン帝国の分割</strong>を密約し、さらに1917年には<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">バルフォア宣言</strong></span>でパレスチナにおける<strong class=\"source-bold\">ユダヤ人の建国</strong>を支持したよね。これじゃあ、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">シオニズム運動</strong></span>を進める<strong class=\"source-bold\">ユダヤ人</strong>と、現地に住んでいる<strong class=\"source-bold\">アラブ人</strong>は絶対に対立するよ！</p>\n<h3><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">アラビア半島では、フセインとイブン＝サウードが対立！</strong></span></h3>\n<p>じゃあ、イギリスから独立を約束された<strong class=\"source-bold\">フセイン</strong>って、誰だろう？ フセインはハーシム家なんだけど……<strong class=\"source-bold\">ハーシム家</strong>って覚えてる？ イスラーム教の創始者<strong class=\"source-bold\">ムハンマドがハーシム家</strong>だ！。つまり、ムハンマドの血統として<strong class=\"source-bold\">メッカのシャリーフ（守護職）</strong>だったから、<strong class=\"source-bold\">イギリスはフセインに接近</strong>したんだよ。そしてフセインは、イギリスの支援で<strong class=\"source-bold\">ヒジャーズ王国</strong>を建てたんだけど、アラブ国家を建設する野望は、ガラガラと崩れていくんだ……。</p>\n<h3><strong class=\"source-bold\">＋<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">α</strong></span>ちょっと寄り耳<span data-source-marker=\"curved-arrow\" data-source-color=\"black\" style=\"color:#222222\">⤴</span></strong></h3>\n<blockquote><p><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ワッハーブ派</strong></span>は、18世紀半ばに<strong class=\"source-bold\">イブン＝アブドゥル＝ワッハーブ</strong>がつくったスンナ派の一派で、イスラーム<ruby>復古<rt>ふっこ</rt></ruby>主義を唱えていたグループだ。</p>\n<p>復古主義（原理主義）とは「ムハンマドの時代に戻ろう！」って考え方なんだけど、いろんな方向性があるよ。最近のニュースで出てくるイスラーム原理主義のテロ組織は「ムハンマドがジハード（<ruby>聖戦<rt>せいせん</rt></ruby>）をやれって言ったから、ムスリムは武器を取って戦わなければいけない！」って考えている連中だ。もちろん復古主義の人が全員テロリストってわけじゃないよ。</p>\n<p>ほかにも「ムハンマドの時、イスラームの中心だったアラブ人のイスラーム国家を取り戻そう！」って主張もあって、ワッハーブ派はこのグループだ。だから、アラビア半島の豪族<strong class=\"source-bold\">サウード家</strong>が保護したんだね。そして1744年、サウード家を中心に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ワッハーブ王国</strong></span>を建国したけど、19世紀前半にエジプトのムハンマド＝アリーに征服されてしまったんだ。これがのちに復活して、フセインと対立するイブン＝サウードの国になるんだよ。</p></blockquote>",
  "299": "<h2>299</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">2</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">戦間期の西アジア・アラブ諸国</u></p>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td></tr><tr><td><strong class=\"source-bold\">レバノン（仏）</strong></td><td><strong class=\"source-bold\">シリア（仏）</strong></td><td><strong class=\"source-bold\">イラク（英）</strong></td></tr><tr><td><strong class=\"source-bold\">パレスチナ（英）</strong></td><td><strong class=\"source-bold\">ヨルダン（英）</strong></td><td></td></tr><tr><td>スエズ運河</td><td></td><td><strong class=\"source-bold\">ネジド王国</strong></td></tr><tr><td><strong class=\"source-bold\">エジプト</strong></td><td><span data-source-marker=\"outline-arrow\" data-source-color=\"red\" style=\"color:#e52715\">⇙</span> 征服</td><td></td></tr><tr><td><strong class=\"source-bold\">ヒジャーズ王国</strong><br>［1924年滅亡］</td><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">サウジアラビア王国</strong></span><br>［1932年成立］</td><td></td></tr><tr><td><strong class=\"source-bold\">イエメン</strong></td><td></td><td>（イギリス領）</td></tr></tbody></table></div>\n<blockquote><p>アラブの国際関係のウラには、ハーシム家とサウード家の対立があるよ！</p></blockquote>\n<p>まず、英仏は<strong class=\"source-bold\">アラブ人への独立の約束を無視</strong>して、<strong class=\"source-bold\">シリア・レバノン</strong>をフランス、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">イラク</strong></span>・<strong class=\"source-bold\">ヨルダン</strong>を<strong class=\"source-bold\">イギリス</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">委任統治領</strong></span>として分割してしまった。しかも、アラビア半島では、<strong class=\"source-bold\">ワッハーブ王国の復活</strong>を目指す<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">サウード家</strong></span>が勢力を拡大していたんだ。1924年、<strong class=\"source-bold\">ネジド王</strong>だった<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">イブン＝サウード</strong></span> <strong class=\"source-bold\">【</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アブド＝アルアジーズ</strong></span><strong class=\"source-bold\">】</strong>がヒジャーズ王国のフセインを破って、<strong class=\"source-bold\">ヒジャーズ＝ネジド王国</strong>をつくると、イギリスとジェッダ条約を結んで、<strong class=\"source-bold\">独立を承認された</strong>。そして、<strong class=\"source-bold\">イブン＝サウード</strong>は全イスラーム会議を開いて、「自分がメッカ・メディナの2つの聖都の守護者である」と宣言、1932年に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">サウジアラビア王国</strong></span>を建国したんだ。さらに、国内でとんでもなく<strong class=\"source-bold\">大きな油田が発見</strong>されたから、この<strong class=\"source-bold\">石油資源をめぐって、サウジアラビアの戦略的な重要性は一気に高まった</strong>よ。これ以後、<strong class=\"source-bold\">ハーシム家</strong>と<strong class=\"source-bold\">サウード家</strong>の対立が続くんだけど……、ほかのアラブ諸国を見ながら話そう！</p>\n<h3><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">英仏の委任統治になったアラブ諸国はどうなったんだろう？</strong></span></h3>\n<p><strong class=\"source-bold\">イギリスはフセイン・マクマホン協定を無視</strong>して独立を認めなかったから、「こうなったら、意地でも独立だ〜」って、<strong class=\"source-bold\">アラブ人たちは怒った</strong>！ そこで、アラブの民族主義者たちはフセインの息子<strong class=\"source-bold\">ファイサル</strong>をシリア王、アブドゥッラーをイラク王として独立を宣言した。でも、<strong class=\"source-bold\">英仏両国</strong>はこれを<ruby>潰<rt>つぶ</rt></ruby>して、サンレモ会議でアラブを委任統治とすることを決めたんだ。この時、1つだったはずの「シリア」は「<strong class=\"source-bold\">シリア、レバノン、ヨルダン</strong>」の3つに分割されちゃった。</p>\n<p>まずイギリスの委任統治となった<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">イラク</strong></span>では、イギリスがアラブ人に妥協して、シリア王になれなかったフセインの息子<strong class=\"source-bold\">ファイサル</strong>を<strong class=\"source-bold\">イラク国王</strong>にしたよ。ってことで、<strong class=\"source-bold\">イラクはハーシム家の国</strong>だね。そして、同じくハーシム家の国になったのが、イラクの隣の<strong class=\"source-bold\">トランスヨルダン</strong>だ。イラク国王になれなかったアブドゥッラーは、イギリスにムカついてヨルダンに攻め込み、さらにシリアへの<ruby>侵攻<rt>しんこう</rt></ruby>も狙っていた。仕方なくイギリスは、アブドゥッラーをトランスヨルダン（ヨルダン川東岸のみの</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦間期と第二次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "300": "<h2>300</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第16回</strong></span> 戦間期の西アジア・南アジア・東南アジア</p>\n<p>呼び名）の首長にしたんだ。こうして、<strong class=\"source-bold\">ハーシム家が国王となったイラクとトランスヨルダン</strong>が連携してアラブ主義を主張し、アラブの<ruby>覇権<rt>はけん</rt></ruby>をめぐって<strong class=\"source-bold\">サウジアラビアと対立</strong>したよ。</p>\n<p>続いて、フランスの委任<ruby>統治領<rt>とうちりょう</rt></ruby>ね。<strong class=\"source-bold\">シリア</strong>では、フランスがイスラーム教の<strong class=\"source-bold\">宗派対立</strong>（シーア派系の<strong class=\"source-bold\">ドルーズ派</strong>やスンナ派）<strong class=\"source-bold\">を利用した分断統治</strong>をおこない、民族運動を抑え込んだ。さらに<strong class=\"source-bold\">レバノン</strong>では、フランスがマロン派キリスト教（単性論の一派）を保護して利権を拡大したんだけど、イスラーム教ドルーズ派はこれに反発したよ。</p>\n<p>こんなふうに、英仏両国が好き勝手に国境や支配者を決めちゃったから、現代までアラブ諸国は不安定な政治状況が続いているんだね。</p>\n<h3><strong class=\"source-bold\">〈アラブ諸国の独立〉</strong></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td>国名</td><td>独立</td><td>委任統治</td><td></td></tr><tr><td>イラク</td><td>1932</td><td>イギリス</td><td><span data-source-color=\"green\" style=\"color:#315837\">●</span> <strong class=\"source-bold\">ファイサル</strong>を国王に王国が成立 ［1921］<br><span data-source-color=\"green\" style=\"color:#315837\">➡</span>1932年、独立承認</td></tr><tr><td>トランスヨルダン</td><td>1946</td><td>イギリス</td><td><span data-source-color=\"green\" style=\"color:#315837\">●</span> ヨルダン川東岸をトランスヨルダンとする<br><span data-source-color=\"green\" style=\"color:#315837\">➡</span>トランスヨルダン王国が名目的独立 ［1928］<br><span data-source-color=\"green\" style=\"color:#315837\">➡</span>正式に独立 ［1946］</td></tr><tr><td>シリア</td><td>1946</td><td>フランス</td><td><span data-source-color=\"green\" style=\"color:#315837\">●</span> 自治権を承認 ［1936］<br><span data-source-color=\"green\" style=\"color:#315837\">➡</span>シリア共和国として独立 ［1946］</td></tr><tr><td>レバノン</td><td>1943</td><td>フランス</td><td><span data-source-color=\"green\" style=\"color:#315837\">●</span> 独立を宣言 ［1941］<br><span data-source-color=\"green\" style=\"color:#315837\">➡</span>共和国となり独立を達成 ［1943］</td></tr><tr><td>イエメン</td><td>1918</td><td>－</td><td><span data-source-color=\"green\" style=\"color:#315837\">●</span> トルコ軍の撤兵とともにイエメン王国として独立<br>シーア派の一派ザイド派による</td></tr></tbody></table></div>\n<h3><span data-source-color=\"brown\" style=\"color:#a43725\"><strong class=\"source-bold\">〈エジプト〉</strong></span></h3>\n<h3><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">第一次世界大戦後に独立を達成したエジプト。でも条件付きだよ……</strong></span></h3>\n<p><strong class=\"source-bold\">ウラービー運動</strong>ののち、イギリスは<strong class=\"source-bold\">エジプト</strong>を<ruby>占領<rt>せんりょう</rt></ruby>して事実上の保護国にしたけど、第一次世界大戦でオスマン帝国が参戦したから、イギリスは正式に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">エジプトを保護国</strong></span>にしたよ。エジプトにしてみれば、たいして変わらないんだけど。</p>\n<p>そして、大戦でイギリス軍に協力させられたエジプトでは、終戦後に<strong class=\"source-bold\">パリ<ruby>講和<rt>こうわ</rt></ruby>会議に代表（「ワフド」）を送る運動</strong>が起きた。この運動を進めたのがのちの<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ワフド党</strong></span>だよ。ていうか、講和会議に代表を送るのは参戦した「独立国」ってことだから、これは<strong class=\"source-bold\">イギリスに対する独立要求</strong>だ。彼らは1919年に反英独立運動を起こしたんだけど、指導者のサアド＝ザグルールは逮捕されちゃった。この<strong class=\"source-bold\">1919年革命</strong>をきっかけに、全国で独立運動が盛り上がったんだ。</p>\n<p>これに対し、大戦後に<strong class=\"source-bold\">世界各地の植民地で独立運動が起きちゃったイギリス</strong>は、</p>",
  "301": "<h2>301</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">3</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">インドの民族運動</u></p>\n<p>「エジプトは形だけでも独立を認めて、ごまかしとけ……」と思って、<strong class=\"source-bold\">一方的にエジプト独立を宣言</strong>したよ（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">エジプト王国</strong></span>）。ただ、<strong class=\"source-bold\">エジプト防衛権</strong>、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スエズ運河地帯の<ruby>駐兵<rt>ちゅうへい</rt></ruby>権</strong></span>、<strong class=\"source-bold\">スーダンの領有権</strong>はそのままイギリスが持ってたから、こんなもんまともな独立じゃないよ。</p>\n<p>納得いかないエジプトの人たちは、「<strong class=\"source-bold\">完全独立させろ〜</strong>」って運動を続けた。そして、独立を求めるワフド党が議会でも勢力を拡大して政権に<ruby>就<rt>つ</rt></ruby>いたから、イギリスは「スエズ運河だけ残れば、ほかはいらないだろ……」って思ったの。こうして1936年には<strong class=\"source-bold\">エジプト＝イギリス同盟条約</strong>が結ばれて、イギリスが<strong class=\"source-bold\">エジプトにほぼ完全な独立を認めた</strong>んだ。この時も<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スエズ運河地帯</strong></span>とスーダンへの駐兵権だけは<strong class=\"source-bold\">イギリスが持ち続けた</strong>よ。</p>\n<blockquote><p>イギリスは、スエズ運河地帯の駐兵権だけは、意地でも手放さないよ！</p></blockquote>\n<p>そして、イギリスに妥協しているワフド党に反発した連中は、<strong class=\"source-bold\">ハサン＝アルバンナ</strong>を中心に<strong class=\"source-bold\">ムスリム<ruby>同胞団<rt>どうほうだん</rt></ruby></strong>をつくった。彼らは、コーランを憲法とするイスラーム国家をつくるって主張したんだ。コーランに基づく国をつくるっていうのも、ムハンマド時代に戻ろうとする動きだから、<strong class=\"source-bold\">イスラーム原理主義</strong>だね。</p>\n<h2><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">3</strong></span> <span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">インドの民族運動</strong></span></h2>\n<h3><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">大戦中にイギリスが「戦後の自治」を約束。インド人は戦争に協力した！</strong></span></h3>\n<p>第一次世界大戦前、イギリスは<strong class=\"source-bold\">インドの宗教対立を利用して民族運動を抑え込んでいた</strong>から、<strong class=\"source-bold\">ヒンドゥー教</strong>を中心とする<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国民会議派</strong></span>は反英、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">全インド＝ムスリム連盟</strong></span>は親英だったよね。そして大戦が<ruby>勃発<rt>ぼっぱつ</rt></ruby>すると、インドは<strong class=\"source-bold\">自動的にイギリス側で参戦</strong>させられたから、インド人は「自分たちが犠牲になってるんだから、自治権くらいよこせ！」と要求し始めた。しかも、親英だったはずのイスラーム教徒も「カリフの国トルコと戦うなんて許せない」って反発し始めたんだ。こうしてインドでは、<strong class=\"source-bold\">ヒンドゥー教徒とイスラーム教徒が反英で協力</strong>することになったよ（ラクナウ協定）。</p>\n<p>「インド人が団結したら抑えられない……」、イギリスのインド相モンタギューは焦った。そこで「戦争に協力してくれたら、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦後に自治</strong></span>を<strong class=\"source-bold\">認めよう</strong>！」って約束して、<strong class=\"source-bold\">民族運動を抑え込む</strong>と同時に<strong class=\"source-bold\">インド人を戦争に動員</strong>しようとしたんだ。はなからこんな約束、イギリスは守る気ないだろ。でも、アメリカ大統領ウィルソンが「<strong class=\"source-bold\">民族<ruby>自決<rt>じけつ</rt></ruby></strong>」を宣言していたこともあって、インドの人たちの多くは「戦争に協力すれば自治権がもらえる」って期待してたんだ。その一人だった<strong class=\"source-bold\">ガンディー</strong>は、「自治権獲得のために戦争に協力しよう！」って主張し、実際に140万人以上のインド人がイギリス兵として参戦したんだ。</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦間期と第二次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "302": "<h2>302</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第16回</strong></span> 戦間期の西アジア・南アジア・東南アジア</p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">クローズアップ</span> <span data-source-color=\"black\" data-source-background=\"pink\" style=\"color:#222222;background-color:#f0a0a0\"><strong class=\"source-bold\">インドの民族運動</strong></span></h3>\n<blockquote><p><span data-source-color=\"red\" style=\"color:#e52715\">●</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦後自治の約束</strong></span>［1917］……イギリスは自治と引き換えに、<strong class=\"source-bold\">インドの戦争協力を求めた</strong></p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span> 第一次世界大戦直後のイギリスの政策</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ローラット法</strong></span>［1919］……<strong class=\"source-bold\"><ruby>令状<rt>れいじょう</rt></ruby>なしの<ruby>逮捕<rt>たいほ</rt></ruby>・裁判抜きの投獄</strong>などを認めた<ruby>弾圧法<rt>だんあつほう</rt></ruby></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span> <strong class=\"source-bold\">アムリットサール事件</strong>［1919］……ローラット法への抗議集会にイギリス軍が発砲</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">インド<ruby>統治法<rt>とうちほう</rt></ruby></strong></span> <strong class=\"source-bold\">【</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1919年インド統治法</strong></span><strong class=\"source-bold\">】</strong> ……<strong class=\"source-bold\">自治の約束とは程遠い</strong>内容</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">非暴力・不服従</strong></span>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">サティヤーグラハ</strong></span>） ……<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ガンディー</strong></span>が提唱</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span> <strong class=\"source-bold\">第1次サティヤーグラハ運動</strong>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">非協力運動</strong></span>） ［1919〜22］ <span data-source-color=\"green\" style=\"color:#315837\">➡</span><strong class=\"source-bold\">ガンディーが停止</strong></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国民会議派ラホール大会</strong></span> ［1929］ ……指導者：<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ネルー</strong></span></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">▶</span>「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">プールナ＝スワラージ</strong></span><strong class=\"source-bold\">【</strong><u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">完全独立</strong></span></u><strong class=\"source-bold\">】</strong>」を宣言、<strong class=\"source-bold\">第2次サティヤーグラハ運動</strong>開始</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span> <strong class=\"source-bold\">第2次サティヤーグラハ運動（不服従運動）</strong> ［1930〜34］ <span data-source-color=\"green\" style=\"color:#315837\">➡</span><strong class=\"source-bold\">塩の行進</strong> ［1930］</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span> イギリスの<ruby>懐柔<rt>かいじゅう</rt></ruby>政策</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span> <strong class=\"source-bold\"><ruby>英印<rt>えいいん</rt></ruby>円卓会議</strong> ［1930〜32］ ……<strong class=\"source-bold\">マクドナルド内閣がロンドンで計3回</strong>開催</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">新インド統治法</strong></span> <strong class=\"source-bold\">【</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1935年インド統治法</strong></span><strong class=\"source-bold\">】</strong></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">▶</span> <strong class=\"source-bold\">11州には全面的な自治制</strong>を採用。<strong class=\"source-bold\">ビルマはインド連邦から完全分離</strong></p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">全インド＝ムスリム連盟</strong></span>の民族運動……独立しても少数派となることを警戒</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span> ムスリム連盟ラホール大会 ［1940］ ……指導者：<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ジンナー</strong></span></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">▶</span> ムスリムの清浄な国家「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">パキスタン</strong></span>」の建設（<strong class=\"source-bold\">分離独立</strong>）を決議</p></blockquote>\n<h3><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">自治の約束は無視！ 怒ったガンディーが非協力運動を始めた！</strong></span></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td></tr><tr><td><strong class=\"source-bold\">パンジャーブ地方</strong></td><td><span data-source-marker=\"point\" data-source-color=\"black\" style=\"color:#222222\">○</span><em data-source-italic=\"true\" style=\"font-style:italic\">ラホール</em></td><td><span data-source-marker=\"point\" data-source-color=\"black\" style=\"color:#222222\">○</span><em data-source-italic=\"true\" style=\"font-style:italic\">アムリットサール</em></td></tr><tr><td><em data-source-italic=\"true\" style=\"font-style:italic\">インダス川</em></td><td><em data-source-italic=\"true\" style=\"font-style:italic\">ガンジス川</em></td><td><span data-source-marker=\"point\" data-source-color=\"black\" style=\"color:#222222\">○</span><em data-source-italic=\"true\" style=\"font-style:italic\">カルカッタ</em></td></tr><tr><td><strong class=\"source-bold\">イギリス領インド帝国</strong></td><td></td><td></td></tr></tbody></table></div>\n<p>インド人は、「これだけ協力したんだから、自治が認められるだろ」って思っていた。でも、<strong class=\"source-bold\">イギリスはこれを完全に裏切り</strong>、インド政府が<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ローラット法</strong></span>を発布した。この法律では<strong class=\"source-bold\">令状なしの逮捕・裁判抜きの投獄</strong>が認められていて、民族運動が起きたら徹底的に弾圧できる。でもこれ、何もしてない人を「お前は、何かやりそうだ！」って逮捕できちゃうんだ。しかも、<strong class=\"source-bold\">ローラット法に抗議する市民の集会にイギリス軍が発砲</strong>して1000人以上の死者を出す<strong class=\"source-bold\">アムリットサール事件</strong>まで起きた。これじゃあ、インド人が</p>",
  "303": "<h2>303</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">3</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">インドの民族運動</u></p>\n<p>怒るのも当たり前だよ！</p>\n<p>さらに、1919年にイギリスが制定した<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">インド統治法</strong></span> <strong class=\"source-bold\">【</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1919年インド統治法</strong></span><strong class=\"source-bold\">】</strong>は、インド人をますます怒らせた。だって、インドの軍事・外交・<ruby>関税<rt>かんぜい</rt></ruby>などの<strong class=\"source-bold\">中央行政</strong>に関する権限は<strong class=\"source-bold\">イギリス人のインド総督</strong>が握っているし、州の<strong class=\"source-bold\">治安（警察）</strong>、<strong class=\"source-bold\">司法</strong>、<strong class=\"source-bold\">徴税</strong>などの重要な権限も<strong class=\"source-bold\">イギリス人の州知事</strong>が持っていて、<strong class=\"source-bold\">州レベル</strong>の、しかも<strong class=\"source-bold\">民生関係のごく一部</strong>（教育、医療、農業、漁業など）の権限が、<strong class=\"source-bold\">インド人も含む州政府</strong>に与えられただけだもん。こんなの、全然自治じゃないよね。</p>\n<p>これに対して<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ガンディー</strong></span>は、<strong class=\"source-bold\">南アフリカでインド人移民の差別撤廃</strong>のためにおこなった非暴力運動をもとに、「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">非暴力・不服従</strong></span>」を掲げて<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">非協力運動</strong></span>を開始し、「民衆が真理に従うための行動だ！」って意味の「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">サティヤーグラハ</strong></span>」と名づけた。<strong class=\"source-bold\">不当な法令に一切従わない</strong>ことや、納税の拒否、そして、インド全土で商店、市場、工場、港などが一斉に休業する<strong class=\"source-bold\">ハルタール</strong>を呼びかけた。さらに、<strong class=\"source-bold\"><ruby>糸紡<rt>いとつむ</rt></ruby>ぎ<ruby>車<rt>くるま</rt></ruby>【チャルカ】を独立運動のシンボル</strong>として、イギリス製品の<ruby>不買<rt>ふばい</rt></ruby>運動を実施した。これがインドの民衆にどんどん広がっていったんだ。</p>\n<p>また、サティヤーグラハ運動には<strong class=\"source-bold\">宗教的な行動がなかった</strong>から、ヒンドゥー教徒だけではなく、<strong class=\"source-bold\">イスラーム教徒も含む大衆運動に発展</strong>したよ。当時、カリフ制を廃止したトルコをイギリスが承認したから、ムスリムがイギリスに反発して<strong class=\"source-bold\">カリフ<ruby>擁護<rt>ようご</rt></ruby>運動（ヒラーファト運動）</strong>をやっていた。ガンディーは、「一緒にイギリスに反対しよう！」って呼びかけ、ムスリムとも協力したんだよ。これにはイギリスも困った。だって、インドの民衆を全員逮捕するわけにいかないでしょ？ 刑務所あふれちゃうじゃん。</p>\n<blockquote><p>非協力運動は、インドの伝統的な価値観をもとにしたから、民衆がすすんで参加したんだ</p></blockquote>\n<p>ただね、運動が盛り上がるにつれて各地で警察との衝突が起き始めたから、民衆が暴力的になることを恐れて、<strong class=\"source-bold\">ガンディーは非協力運動の停止を決めた</strong>んだ。ここからしばらくの間、インドの民族運動は停滞するけど、確実に<strong class=\"source-bold\">イギリスに対する反感は広がっていた</strong>よ。例えば、<strong class=\"source-bold\">インド共産党</strong>の結成もこの時期だよ。</p>\n<h3><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">イギリスの不誠実な対応から、国民会議派はついに「完全独立」を決議！</strong></span></h3>\n<p>インドの民族運動が広がるのを見て、イギリス本国では<strong class=\"source-bold\">労働党</strong>が「<strong class=\"source-bold\">インド統治法を改正したほうがよいのでは</strong>……」と言い始めた。<strong class=\"source-bold\">保守党</strong>のボールドウィン内閣は「もし労働党が選挙で勝ったら、インドの改革が急激に進むのでは……」と焦って、改革をなるべく進めないために、保守党が先手を打って「中途半端に」改革することにしたんだ。</p>\n<p>こうして、<strong class=\"source-bold\">インド統治法を改正する準備</strong>として<strong class=\"source-bold\">憲政改革調査委員会【サイモン委員会】</strong>が派遣されたんだけど、委員のなかに<strong class=\"source-bold\">インド人が1人もいなかった</strong>から、か</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦間期と第二次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "304": "<h2>304</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第16回</strong></span> 戦間期の西アジア・南アジア・東南アジア</p>\n<p>えって<strong class=\"source-bold\">民族運動を激化</strong>させた。この動きに焦ったイギリスは、「将来、インドを自治領にする」と宣言したんだけど、国民会議派は「将来っていつだよ」って、もっと怒った！ こんな約束は第一次世界大戦後に、すでに裏切られてるじゃないか。</p>\n<p>1929年、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国民会議派</strong></span>は<strong class=\"source-bold\">パンジャーブ地方</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ラホール</strong></span>で大会を開き、若い<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ネルー</strong></span>を指導者として、今後の目標が「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">プールナ＝スワラージ</strong></span>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">完全独立</strong></span>）」であることを宣言した。さらに、イギリスが開催を呼びかけていた<strong class=\"source-bold\"><ruby>円卓<rt>えんたく</rt></ruby>会議のボイコット</strong>と<strong class=\"source-bold\">第2次サティヤーグラハ運動（不服従運動）</strong>への突入を決議し、これに基づいてガンディーは「<strong class=\"source-bold\">塩の行進</strong>」を始めたんだ。これは、イギリスが制定した<strong class=\"source-bold\">塩の<ruby>専売法<rt>せんばいほう</rt></ruby>に反対</strong>して、民衆とともに塩をつくるために海岸に向かって行進するって運動だよ。でも、この運動に一番びっくりしたのは、ネルーら国民会議派の若い指導者たちだった。だって、ラホール大会で決議したはずの「<strong class=\"source-bold\">完全独立</strong>」じゃなくて、「<strong class=\"source-bold\">塩の専売反対</strong>」って<strong class=\"source-bold\">スローガン</strong>なんだもん。</p>\n<blockquote><p>目標が「自治」から「完全独立」に変わったのがラホール大会だ</p></blockquote>\n<p>ただ、「塩の行進」はイギリスにはかなり打撃を与えたんだ。塩税は当時のインド政府の税収の第3位だったし、世界中から「イギリスは、塩までインド人から取り上げているのか……！」と<strong class=\"source-bold\">インド支配の不当性が非難された</strong>。しかも、逮捕されたガンディーは、「釈放されるまで<ruby>断食<rt>だんじき</rt></ruby>する」って言うし……。ガンディーが<ruby>飢<rt>う</rt></ruby>え<ruby>死<rt>じ</rt></ruby>にしたら、それこそ大事件だよ。こうして、イギリスと闘うガンディーの名前は世界的に有名になった。さらに、コミンテルン第7回大会で「人民戦線」戦術が<ruby>採択<rt>さいたく</rt></ruby>されると、<strong class=\"source-bold\">インド共産党が国民会議派と統一戦線を結成</strong>するなど、民族運動はどんどん大きくなっていったんだ。</p>\n<h3><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">イギリスの<ruby>懐柔<rt>かいじゅう</rt></ruby>策によって、再びヒンドゥーとイスラームの対立が激化！</strong></span></h3>\n<p>さすがのイギリスもいい加減に困った。しかも、1929年に起こった<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">世界<ruby>恐慌<rt>きょうこう</rt></ruby></strong></span>で、本国の経済は最悪！ こりゃ、恐慌から立ち直るためにもインドの協力が必要だもん。そこで、イギリスの<strong class=\"source-bold\">マクドナルド内閣</strong>は<strong class=\"source-bold\">ロンドン</strong>に<strong class=\"source-bold\">インド側の代表</strong>を招き、<strong class=\"source-bold\">3回</strong>にわたる<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">英印円卓会議</strong></span> <strong class=\"source-bold\">【</strong>ロンドン円卓会議<strong class=\"source-bold\">】</strong>を開いて、インド統治法の改正について話し合った。でも、<strong class=\"source-bold\">国民会議派</strong>のメンバーは出席を<strong class=\"source-bold\">ボイコット</strong>して不服従運動を続け、<strong class=\"source-bold\">第2回にガンディーのみが出席</strong>したけど、ほとんどなんの成果も上げられなかった。一方で、少数派のムスリムが少しでも有利になるように、<strong class=\"source-bold\">全インド＝ムスリム連盟</strong>は<strong class=\"source-bold\">イギリスに協力</strong>したんだ。</p>\n<p>こうして<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">新インド統治法</strong></span> <strong class=\"source-bold\">【</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1935年インド統治法</strong></span><strong class=\"source-bold\">】</strong>が制定され、<strong class=\"source-bold\"><ruby>藩王国<rt>はんおうこく</rt></ruby>とイギリス領11州</strong>で<strong class=\"source-bold\">インド連邦</strong>を形成することを定めた。インド<ruby>総督<rt>そうとく</rt></ruby>・州知事の任免権はイギリスが持っていたから完全な自治ではないけど、<strong class=\"source-bold\">11州には全面的な自治が認められ</strong>、自治議会も選挙で選ばれることになった。この時<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ビルマ</strong></span>は<strong class=\"source-bold\">インド連邦から完全</strong></p>",
  "305": "<h2>305</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">4</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">東南アジアの民族運動</u></p>\n<p>分離されたよ。そして<strong class=\"source-bold\">自治議会の選挙</strong>がおこなわれると、結果は<strong class=\"source-bold\">国民会議派などヒンドゥー勢力が圧勝</strong>！ 11州のうち9州で国民会議派が第1党となり、州政府の中心になった。この結果がインド内部の対立を激化させたんだ。</p>\n<p>選挙結果は<strong class=\"source-bold\">全インド＝ムスリム連盟</strong>にとって、すごくショックだった。だって、もしこのままインドが独立できたとしても、<strong class=\"source-bold\">ムスリムは少数派のまま政権に就けず</strong>、下手するとヒンドゥー教徒に<ruby>弾圧<rt>だんあつ</rt></ruby>されるかもしれない……。実際、選挙の結果がそれを証明しちゃったんだもん。「独立するなら、ヒンドゥー教徒とは別の国で！」、そう思った<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">全インド＝ムスリム連盟</strong></span>は、1940年、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ジンナー</strong></span>を指導者とするムスリム連盟の<strong class=\"source-bold\">ラホール大会</strong>で、ムスリムの清浄な国「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">パキスタン</strong></span>」の建設、つまりは<strong class=\"source-bold\">分離独立を決議</strong>したんだ。</p>\n<blockquote><p>ヒンドゥー教徒が盛り上がれば盛り上がるほど、少数派のムスリムは焦ったんだ</p></blockquote>\n<p>そして、<strong class=\"source-bold\">この対立はインド独立まで続く</strong>ことになるよ。第二次世界大戦が始まっても、<strong class=\"source-bold\">国民会議派</strong>はガンディーを中心に<strong class=\"source-bold\">不服従運動を続け</strong>、さらには「<strong class=\"source-bold\">クイット＝インディア</strong>（インドから出ていけ！ つまり<strong class=\"source-bold\">即時独立</strong>ってこと）」を要求するなど、どんどん過激な運動をやったから、<strong class=\"source-bold\">非合法とされて弾圧された</strong>んだ。また、国民会議派の<strong class=\"source-bold\">チャンドラ・ボース</strong>はインド国民軍を組織して、<strong class=\"source-bold\">日本のインド<ruby>侵攻<rt>しんこう</rt></ruby>作戦（インパール作戦）に協力</strong>することで、インドの解放を目指したんだ。一方、<strong class=\"source-bold\">ムスリム連盟</strong>は、インド独立の際に「ヒンドゥー国家とイスラーム国家」を分離独立させてくれるようイギリスに働きかけ、そのために<strong class=\"source-bold\">第二次世界大戦ではイギリスに協力</strong>したんだよ。こうして、ヒンドゥー教徒とイスラーム教徒の対立は、もはや修復不可能になっちゃった。そして、第二次世界大戦後に独立する際には、<strong class=\"source-bold\">ヒンドゥー教徒</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">インド</strong></span>と<strong class=\"source-bold\">イスラーム教徒</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">パキスタン</strong></span>は別々の国になっちゃったんだ。</p>\n<h2><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">4</strong></span> <span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">東南アジアの民族運動</strong></span></h2>\n<h3><span data-source-color=\"brown\" style=\"color:#a43725\"><strong class=\"source-bold\">〈ビルマ〉</strong></span></h3>\n<h3><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">インド帝国の一部にされたビルマでも民族運動が起こった！</strong></span></h3>\n<p><strong class=\"source-bold\">ビルマ（現在のミャンマー）</strong>は<strong class=\"source-bold\">イギリス領インド帝国に編入</strong>されてしまったけど、その扱いはインドよりもひどかったんだよ。例えば、インドでは部分的に認められた自治権さえ、ビルマには認められなかったんだもん。しかも、民族運動が全然1つにまとまらない……。これにしびれを切らしたのが、元僧侶の<strong class=\"source-bold\">サヤー＝サン</strong>らの過激な民族運動家だ。彼らは農民をまとめて<strong class=\"source-bold\">イギリスに対する反乱</strong>を起こし、一時は全土に農民反乱が広がったけど<ruby>鎮圧<rt>ちんあつ</rt></ruby>され、<strong class=\"source-bold\">サヤー＝サンは処刑</strong>されてしまった。</p>\n<p>その後、<strong class=\"source-bold\">新インド<ruby>統治法<rt>とうちほう</rt></ruby>の制定</strong>にあわせて<strong class=\"source-bold\">ビルマ統治法</strong>もつくられ、ビルマでも</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦間期と第二次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "306": "<h2>306</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第16回</strong></span> 戦間期の西アジア・南アジア・東南アジア</p>\n<p>自治権が拡大されたよ。ただ、ビルマの民族主義者たちは「将来、自治領になった時に権力を握りたい！」と、権力闘争を始めてしまったんだ！。この混乱のなかから登場したのが、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">タキン党</strong></span>だよ。正式名は「<strong class=\"source-bold\">我らのビルマ協会</strong>」だ。党員たちは名前の前に「タキン（“主人”って意味だよ）」をつけてお互いを呼び合い、「ビルマの主人はイギリスじゃなくてビルマ人だ」っていう強い想いを表現したよ。</p>\n<p>そして第二次世界大戦中に、この団体の指導者となったのが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アウン＝サン</strong></span>だ。彼は、当初イギリスからの独立を目指して<strong class=\"source-bold\">日本軍に協力</strong>したんだけど、日本が独立を助けてくれるのではなく軍政を敷いたので、1944年には<strong class=\"source-bold\">反ファシスト人民自由連盟</strong>を組織して、<strong class=\"source-bold\"><ruby>抗日<rt>こうにち</rt></ruby>運動に転換</strong>したんだ。</p>\n<p>第二次世界大戦後、彼らが<strong class=\"source-bold\">イギリスと交渉して独立することが決まった</strong>んだけど、その直後に<strong class=\"source-bold\">アウン＝サンは政敵によって暗殺</strong>されてしまった。戦後のビルマの民主化運動の指導者<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スー＝チー</strong></span> <strong class=\"source-bold\">【</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アウン＝サン＝スー＝チー</strong></span><strong class=\"source-bold\">】</strong>は、彼の長女だよ。</p>\n<h3><strong class=\"source-bold\">〈戦間期の東南アジア〉</strong></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td></tr><tr><td>ビルマ</td><td><span data-source-marker=\"point\" data-source-color=\"black\" style=\"color:#222222\">○</span><em data-source-italic=\"true\" style=\"font-style:italic\">ハノイ</em></td><td><span data-source-marker=\"point\" data-source-color=\"black\" style=\"color:#222222\">○</span><em data-source-italic=\"true\" style=\"font-style:italic\">マニラ</em></td></tr><tr><td>ラオス</td><td>タイ</td><td><strong class=\"source-bold\">フィリピン</strong></td></tr><tr><td>カンボジア</td><td><strong class=\"source-bold\">フランス領インドシナ連邦</strong></td><td></td></tr><tr><td></td><td><span data-source-marker=\"point\" data-source-color=\"black\" style=\"color:#222222\">○</span><em data-source-italic=\"true\" style=\"font-style:italic\">サイゴン</em></td><td>北ボルネオ</td></tr><tr><td><strong class=\"source-bold\">マレー連合州</strong></td><td><span data-source-marker=\"point\" data-source-color=\"black\" style=\"color:#222222\">○</span><em data-source-italic=\"true\" style=\"font-style:italic\">シンガポール</em></td><td>南ボルネオ<br>【カリマンタン】</td></tr><tr><td>スマトラ島</td><td><strong class=\"source-bold\">オランダ領東インド</strong></td><td></td></tr><tr><td></td><td><span data-source-marker=\"point\" data-source-color=\"black\" style=\"color:#222222\">○</span><em data-source-italic=\"true\" style=\"font-style:italic\">バタヴィア</em></td><td>ジャワ島</td></tr></tbody></table></div>\n<p><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">太平洋戦争中の日本軍の最大勢力範囲［1942］</span></p>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td></tr><tr><td><span data-source-marker=\"area\" data-source-color=\"red\" style=\"color:#ee8080\">■</span> イギリス領</td></tr><tr><td><span data-source-marker=\"area\" data-source-color=\"gray\" style=\"color:#a6aaa0\">■</span> フランス領</td></tr><tr><td><span data-source-marker=\"area\" data-source-color=\"pink\" style=\"color:#f4cccc\">■</span> オランダ領</td></tr><tr><td><span data-source-marker=\"area\" data-source-color=\"green\" style=\"color:#4e6a43\">■</span> アメリカ領</td></tr></tbody></table></div>\n<blockquote><p>太平洋戦争中の日本軍の影響も一緒に考えよう！</p></blockquote>",
  "307": "<h2>307</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">4</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">東南アジアの民族運動</u></p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦間期と第二次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>\n<h3><span data-source-color=\"brown\" style=\"color:#a43725\"><strong class=\"source-bold\">〈インドシナ（ベトナム）〉</strong></span></h3>\n<h3><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">反仏から反日へ！ ひたすらベトナム独立のために戦ったホー＝チ＝ミン</strong></span></h3>\n<p>第一次世界大戦後のベトナムでも、<strong class=\"source-bold\">フランスに対する民族運動</strong>が起こったよ。1925年、かつて<ruby>東遊<rt>ドンズー</rt></ruby>運動を指導していた<strong class=\"source-bold\">ファン＝ボイ＝チャウが逮捕</strong>されると、ベトナム各地でデモがおこり、民族運動が全国に拡大したよ。こうした運動のなかで、グエン＝タイ＝ホクを中心に<strong class=\"source-bold\">ベトナム国民党</strong>が結成され、<strong class=\"source-bold\">中国国民党をモデルに民族革命を目指した</strong>。しかし、<ruby>要人<rt>ようじん</rt></ruby>の暗殺事件をきっかけにフランスが<ruby>弾圧<rt>だんあつ</rt></ruby>し、<strong class=\"source-bold\">反乱も<ruby>鎮圧<rt>ちんあつ</rt></ruby></strong>され、運動は崩壊してしまったんだ。</p>\n<blockquote><p>ホー＝チ＝ミンは「仏→日→仏→米」と、ベトナム独立のために、次々変わる敵と戦い続けたんだ</p></blockquote>\n<p>こうしたなかで、着々と活動を進めていたのが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ホー＝チ＝ミン</strong></span>だ。<strong class=\"source-bold\">ロシア革命の影響</strong>でマルクス主義を学び、モスクワでコミンテルンの大会にも出席したホー＝チ＝ミンは、1925年に中国の<ruby>広東<rt>カントン</rt></ruby>で<strong class=\"source-bold\">ベトナム青年革命同志会</strong>をつくり、若者を中心に支持者を増やしていった。そして、1930年いくつかに分かれていた共産主義運動をまとめて、<strong class=\"source-bold\">ベトナム共産党</strong>（同じ年の10月に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">インドシナ共産党</strong></span>に改称したよ）を結成したんだ。</p>\n<p>その後、<strong class=\"source-bold\">ホー＝チ＝ミンは反仏闘争</strong>を進め、さらに第二次世界大戦が始まって日本がフランス領インドシナへと<ruby>進駐<rt>しんちゅう</rt></ruby>すると<strong class=\"source-bold\">反日闘争へと転換</strong>、1941年には<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベトナム独立同盟</strong></span> <strong class=\"source-bold\">【</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベトミン</strong></span><strong class=\"source-bold\">】</strong>を結成して、日本に対する抵抗運動をおこなったんだ。</p>\n<p>大戦末期にいよいよ<strong class=\"source-bold\">アメリカ軍がベトナムに上陸</strong>しそうになると、日本は阮朝最後の君主バオダイを引っ張りだして<strong class=\"source-bold\">ベトナム帝国</strong>をつくり、さらに<strong class=\"source-bold\">カンボジアやラオスの独立</strong>も認めた。これが、ホー＝チ＝ミンにとってはチャンスになったんだ。日本軍の<ruby>降伏<rt>こうふく</rt></ruby>直後に、ホー＝チ＝ミンは<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベトナム民主共和国</strong></span>の独立を宣言した。実はここからが、さらに続く<strong class=\"source-bold\">フランス</strong>、そして<strong class=\"source-bold\">アメリカとの戦い</strong>の始まりだったんだ。</p>\n<h3><span data-source-color=\"brown\" style=\"color:#a43725\"><strong class=\"source-bold\">〈インドネシア〉</strong></span></h3>\n<h3><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">アジア初の共産党の結成。そして、スカルノが国民党を結成した！</strong></span></h3>\n<p>第一次世界大戦前に結成された<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">サレカット＝イスラム</strong></span> <strong class=\"source-bold\">【</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">イスラーム同盟</strong></span><strong class=\"source-bold\">】</strong>が、オランダに弾圧されて力を失っていくなかで、<strong class=\"source-bold\">同盟内の左派グループ</strong>は労働組合と結びついて、<strong class=\"source-bold\">アジア最初の共産党</strong>となる<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">インドネシア共産党</strong></span>をつくったよ。そして、1926年にはジャワ島やスマトラ島で相次いで反乱を起こしたんだけど、<strong class=\"source-bold\">オランダはこれを徹底的に弾圧</strong>したから、共産党は壊滅状態に追い込まれちゃった。</p>\n<p>共産党が崩壊してしまうと、インドネシアの民族運動の中心はオランダに留学したエリートたちになった。彼らは<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スカルノ</strong></span>を中心に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">インドネシア国民党</strong></span>（結成当初は<strong class=\"source-bold\">インドネシア国民同盟</strong>）を結成したよ。スカルノは、これまでに結成されたブディ＝</p>",
  "308": "<h2>308</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第16回</strong></span> 戦間期の西アジア・南アジア・東南アジア</p>\n<p>ウトモやサレカット＝イスラム、共産党などをまとめるために、「インドネシアのイスラームも共産主義も民族主義も、すべて<strong class=\"source-bold\">独立のために統一</strong>されるべきだ！」と主張し、独立運動を展開したよ。この<strong class=\"source-bold\">ムルデカ運動【愛国運動】</strong>では、これまで地域ごとにバラバラだったオランダ領東インドを「インドネシア」として、「1つのインドネシア国民、1つのインドネシア語」という理想を掲げたよ。しかし、この独立運動も<strong class=\"source-bold\">オランダに<ruby>弾圧<rt>だんあつ</rt></ruby></strong>され、<strong class=\"source-bold\">スカルノは逮捕</strong>されてしまったんだ。</p>\n<p>その後、太平洋戦争中に<strong class=\"source-bold\">日本軍がインドネシアを<ruby>占領<rt>せんりょう</rt></ruby></strong>すると、日本はインドネシア人の協力を得るために<strong class=\"source-bold\">スカルノら民族主義者を釈放</strong>した。スカルノは<strong class=\"source-bold\">日本軍と<ruby>連携<rt>れんけい</rt></ruby></strong>しつつ、オランダからの独立準備を進めたよ。例えば、スカルノが日本軍に「インドネシア語が共通語です」と言ったから日本がインドネシア語を<ruby>統治<rt>とうち</rt></ruby>に使い、結果的に<strong class=\"source-bold\">インドネシア語が全国に広まった</strong>。さらに、日本軍がインドネシア人にやらせた軍事訓練にも、「いつか独立戦争を戦う兵士になる」と思って協力したから、実際に<strong class=\"source-bold\">オランダと独立戦争を戦う時の軍団</strong>ができた。こんなふうにスカルノは<strong class=\"source-bold\">日本軍に協力</strong>しつつ利用して、うまいこと独立運動をまとめたんだよ。そして、日本が降伏した直後に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">インドネシア共和国</strong></span>の独立を宣言した。オランダは植民地支配の復活を狙って軍隊を送ってきたけど、4年間の独立戦争を経て、インドネシアは<strong class=\"source-bold\">ハーグ協定</strong>で独立を達成したんだよ。</p>\n<blockquote><p>スカルノは、オランダからの独立のために、うまいこと日本軍を利用したんだよ</p></blockquote>\n<h3><span data-source-color=\"brown\" style=\"color:#a43725\"><strong class=\"source-bold\">〈フィリピン〉</strong></span></h3>\n<h3><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">世界<ruby>恐慌<rt>きょうこう</rt></ruby>に苦しむアメリカが、10年後の独立を約束！</strong></span></h3>\n<p><strong class=\"source-bold\">アメリカが<ruby>統治<rt>とうち</rt></ruby>するフィリピン</strong>では、すでに議会が開設されるなど、フィリピン人に一定の権力が与えられていたんだ。でも、世界恐慌の影響もあって、アメリカへの輸出に経済が依存していたフィリピンでは貧しい農民たちの反乱が相次いだ。だからアメリカの態度が変わったよ。当時のアメリカ大統領<strong class=\"source-bold\">フランクリン＝ローズヴェルト</strong>は、<strong class=\"source-bold\">中南米の国々への干渉を控える<ruby>善隣<rt>ぜんりん</rt></ruby>外交をとっていた</strong>から、植民地のフィリピンも独立させることにした。こうして1934年に<strong class=\"source-bold\">フィリピン独立法</strong>が成立！ アメリカは<strong class=\"source-bold\">10年後の独立を約束</strong>し、翌年には<strong class=\"source-bold\">独立準備政府</strong>がつくられたんだ。ただ、太平洋戦争が始まると日本に占領されちゃったから、<strong class=\"source-bold\">実際に独立したのは戦後になってから</strong>だよ。</p>\n<h3><span data-source-color=\"brown\" style=\"color:#a43725\"><strong class=\"source-bold\">〈タイ〉</strong></span></h3>\n<h3><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">唯一の独立国タイでは立憲革命が起きた！</strong></span></h3>\n<p><strong class=\"source-bold\">タイは独立国</strong>だから、どこかの国に対する独立運動ではなく、そのかわり、国王に対する反対運動が起きたんだ。第一次世界大戦前、ラーマ5世が近代化によって</p>",
  "309": "<h2>309</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">4</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">東南アジアの民族運動</u></p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦間期と第二次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>\n<p>独立を維持したタイだったけど、<strong class=\"source-bold\">ラーマ5世が亡くなる</strong>とだんだんと<strong class=\"source-bold\">専制政治への批判</strong>が強まってきたんだ。そして1932年、若手の軍人や官僚たちが結成した<strong class=\"source-bold\">人民党</strong>を中心に<strong class=\"source-bold\">タイ立憲革命</strong>が起こり、憲法の発布や議会の開設によって<strong class=\"source-bold\">立憲君主政</strong>になったんだ。</p>\n<p>その後、人民党の<strong class=\"source-bold\">ピブン</strong>が首相となり、国号が<strong class=\"source-bold\">シャム</strong>から<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">タイ</strong></span>に変更された。そして太平洋戦争中、<strong class=\"source-bold\">ピブン政権</strong>はかつてフランスに奪われた領土の回復を狙って<strong class=\"source-bold\">日本に接近</strong>し、<strong class=\"source-bold\">日本側で参戦</strong>したよ。日本がフランス領インドシナに進駐したから、これを利用してタイの勢力回復を狙った、ってことだね。</p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">合</span><span data-source-color=\"white\" data-source-background=\"brown\" style=\"color:#ffffff;background-color:#a43725\">否</span><strong class=\"source-bold\">の分かれ目</strong></h3>\n<blockquote><p><span data-source-border=\"brown\" data-source-border-style=\"dotted\" style=\"border:1px dotted #a43725;padding:0 0.2em\"><strong class=\"source-bold\">日本軍の東南アジア占領と民族運動</strong></span></p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span> <strong class=\"source-bold\">ビルマ</strong>……当初、<strong class=\"source-bold\">日本軍に協力</strong>、のちに<strong class=\"source-bold\">反日闘争</strong>に転換</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アウン＝サン</strong></span>……<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">タキン党</strong></span>の指導者。当初、日本軍に協力</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">➡</span><strong class=\"source-bold\">反ファシスト人民自由連盟</strong>を組織 ［1944］</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span> <strong class=\"source-bold\">ベトナム</strong>……<strong class=\"source-bold\">反仏闘争から反日闘争へ</strong></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ホー＝チ＝ミン</strong></span>……<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">インドシナ共産党</strong></span>の指導者</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">➡</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベトナム独立同盟</strong></span> <strong class=\"source-bold\">【</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベトミン</strong></span><strong class=\"source-bold\">】</strong>を結成 ［1941］</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span> <strong class=\"source-bold\">インドネシア</strong>……<strong class=\"source-bold\">日本軍と連携</strong>しつつ、独立運動を準備</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スカルノ</strong></span>……<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">インドネシア国民党</strong></span>の指導者</p></blockquote>\n<p>さて、戦間期のアジアはこれでおしまい。今回出てきた人たちは、アジア各国の独立の英雄が多いから、独立後の各国史（戦後史）でもまた登場するからね〜。</p>\n<p>じゃあ、最後に年号 check！</p>\n<h3><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">！！</strong></span> <span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">年号のツボ</span></h3>\n<blockquote><p><span data-source-color=\"red\" style=\"color:#e52715\">●</span> <strong class=\"source-bold\">オスマン帝国</strong>（<strong class=\"source-bold\">成立〜滅亡</strong>） ［1<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">299</strong></span>〜1<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">922</strong></span>］（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>肉<rt>29</rt></ruby><ruby>食<rt>9</rt></ruby></strong></span>う<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>国<rt>92</rt></ruby><ruby>に<rt>2</rt></ruby></strong></span> <ruby>おお<rt>オ</rt></ruby><ruby>住<rt>ス</rt></ruby><ruby>ま<rt>マ</rt></ruby><ruby>ん<rt>ン</rt></ruby>帝国）</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">➡</span>1922年は「スルタン制の廃止」だよ！</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span> <strong class=\"source-bold\">カリフ制の廃止</strong> ［1<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">924</strong></span>］（カリフの<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>国<rt>92</rt></ruby><ruby>よ<rt>4</rt></ruby></strong></span> 今日から廃止）</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span> <strong class=\"source-bold\">国民会議派ラホール大会</strong> ［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1929</strong></span>］（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>い<rt>1</rt></ruby><ruby>く<rt>9</rt></ruby><ruby>人<rt>2</rt><rt data-source-position=\"below\" style=\"ruby-position:under\">ニ<span data-source-color=\"black\" style=\"color:#222222\">ン</span></rt></ruby><ruby>苦<rt>9</rt></ruby></strong></span>労で 独立決議）</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span> <strong class=\"source-bold\">新インド<ruby>統治法<rt>とうちほう</rt></ruby></strong> ［1<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">935</strong></span>］（インドに<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>組<rt>9</rt></ruby><ruby>み<rt>3</rt></ruby><ruby>込<rt>5</rt></ruby></strong></span>む 自治議会）</p></blockquote>\n<p>次回は、戦間期のアジアの2回目。いよいよ<strong class=\"source-bold\">中国革命</strong>を見ていくよ〜！ <ruby>孫文<rt>そんぶん</rt></ruby>、<ruby>蔣介石<rt>しょうかいせき</rt></ruby>、<ruby>毛沢東<rt>もうたくとう</rt></ruby>……有名人がいっぱいでてくるからね。お楽しみに。</p>"
};

